INSERT INTO `chapitres` VALUES (1,'T.111.111','DWB-T.111.111','Identifier le contexte et les acteurs','https://solicode-web-mobile.github.io/autoformations-web/tutos/identifier-contexte-acteurs/','<p>Comprendre une application à partir de ses maquettes et identifier sa finalité, son périmètre et ses acteurs.</p><p>Prérequis : Les maquettes du Blog personnel sont nécessaires.</p>',1,1,1,1,NULL,'2026-09-07 06:32:42','2026-09-07 06:33:08',0),(2,'T.112.111','DWB-T.112.111','Rôle des données dans une application','https://solicode-web-mobile.github.io/autoformations-web/tutos/r%C3%B4le-donn%C3%A9es/','Comprendre la différence entre information et donnée, et comprendre pourquoi une application utilise des données pour réaliser une fonctionnalité.',1,1,1,2,NULL,'2026-09-07 06:32:42','2026-09-07 06:33:08',0),(3,'T.121.111','DWB-T.121.111','Afficher son nom avec JavaScript','https://solicode-web-mobile.github.io/autoformations-web/tutos/variables-entr%C3%A9es-sorties/','Découvrir JavaScript et Node.js, puis créer et exécuter un programme qui affiche votre nom dans la console.',1,1,1,3,NULL,'2026-09-07 06:32:43','2026-09-07 06:33:08',0),(4,'T.161.11','DWB-T.161.11','Découvrir Google Slides et le partage','https://solicode-web-mobile.github.io/autoformations-web/tutos/partage-google-slides/','Créer une présentation d’une slide pour présenter son profil, puis la partager avec un lien afin que d’autres personnes puissent la consulter.',1,1,1,5,NULL,'2026-09-07 06:32:43','2026-09-07 06:32:43',0),(5,'T.162.111','DWB-T.162.111','Comment apprendre à Solicode ?','https://solicode-web-mobile.github.io/autoformations-web/tutos/apprendre-%C3%A0-solicode/',NULL,1,1,1,9,NULL,'2026-09-07 06:32:43','2026-09-07 06:32:43',0),(6,'T.161.121','DWB-T.161.121','Découvrir le Web et Internet','https://solicode-web-mobile.github.io/autoformations-web/tutos/web-internet/','Comprendre Internet, le Web, le navigateur, le site Web et l’application Web.',1,2,1,6,NULL,'2026-09-07 06:32:43','2026-09-07 06:33:08',0),(7,'T.121.112','DWB-T.121.112','Manipuler les variables','https://solicode-web-mobile.github.io/autoformations-web/tutos/manipuler-variables/','Comprendre ce qu’est une variable et l’utiliser pour stocker et afficher des valeurs en JavaScript.',1,2,1,3,NULL,'2026-09-07 06:32:43','2026-09-07 06:32:43',0),(8,'T.161.131','DWB-T.161.131','Découvrir les langages du Web','https://solicode-web-mobile.github.io/autoformations-web/tutos/langages-du-web/',NULL,1,3,1,7,NULL,'2026-09-07 06:32:43','2026-09-07 06:33:08',0),(9,'T.121.113','DWB-T.121.113','Effectuer des opérations','https://solicode-web-mobile.github.io/autoformations-web/tutos/effectuer-operations','Utiliser les opérations arithmétiques en JavaScript pour calculer un résultat avec des variables.',1,3,1,3,NULL,'2026-09-07 06:32:43','2026-09-07 06:32:43',0),(10,'T.161.141','DWB-T.161.141','Découvrir le métier de développeur','https://solicode-web-mobile.github.io/autoformations-web/tutos/m%C3%A9tier-d%C3%A9veloppeur/',NULL,1,4,1,8,NULL,'2026-09-07 06:32:43','2026-09-07 06:33:08',0),(11,'T.121.114','DWB-T.121.114','Recevoir des données','https://solicode-web-mobile.github.io/autoformations-web/tutos/recevoir-donnees/',NULL,1,4,1,3,NULL,'2026-09-07 06:32:43','2026-09-07 06:32:43',0),(12,'T.121.115','DWB-T.121.115','Exercice : gérer un article','https://solicode-web-mobile.github.io/autoformations-web/tutos/exercice-gerer-article/',NULL,1,5,1,3,NULL,'2026-09-07 06:32:43','2026-09-07 06:32:43',0),(13,'T.121.116','DWB-T.121.116','Échanger deux variables','https://solicode-web-mobile.github.io/autoformations-web/tutos/echanger-deux-variables','Découvrir une première technique algorithmique en JavaScript : échanger les valeurs de deux variables sans les perdre.',1,6,1,3,NULL,'2026-09-07 06:32:43','2026-09-07 06:32:43',0),(14,'T.021.111','DMB-Définir une donnée et un dictionnaire de données','Définir une donnée et un dictionnaire de données','https://solicode-web-mobile.github.io/autoformations-structurer/tutos/definir-donnee-dictionnaire-donnees/',NULL,1,5,1,10,NULL,'2026-09-08 12:52:56','2026-09-09 11:04:53',0),(15,'T.021.112','DMB-T.021.112','Créer le dictionnaire de données d’un Blog','https://solicode-web-mobile.github.io/autoformations-structurer/tutos/creer-dictionnaire-donnees-blog/',NULL,1,6,0,10,NULL,'2026-09-08 12:53:46','2026-09-09 11:04:53',0),(16,'T.201.211','DMB-T.201.211','Échanger les valeurs de deux variables','https://solicode-web-mobile.github.io/autoformations-structurer/tutos/echanger-les-valeurs-de-deux-variables/',NULL,1,1,1,11,NULL,'2026-09-09 06:56:08','2026-09-09 06:56:08',0),(17,'T.201.212','DMB-T.201.212','Rechercher une valeur maximale dans un tableau','https://solicode-web-mobile.github.io/autoformations-structurer/tutos/rechercher-une-valeur-maximale/',NULL,1,2,1,11,NULL,'2026-09-09 06:56:45','2026-09-09 06:56:45',0),(18,'T.201.213','DMB-T.201.213','Parcourir et traiter un tableau','https://solicode-web-mobile.github.io/autoformations-structurer/tutos/parcourir-et-traiter-un-tableau/',NULL,1,3,0,11,NULL,'2026-09-09 06:57:55','2026-09-09 08:16:23',0),(19,'T.201.214','DMB-T.201.214','Trier les éléments d’un tableau','https://solicode-web-mobile.github.io/autoformations-structurer/tutos/trier-tableau/',NULL,1,4,1,11,NULL,'2026-09-09 06:58:22','2026-09-10 12:49:53',0),(20,'T.201.215','DMB-T.201.215','Construire un algorithme à partir d’un problème','https://solicode-web-mobile.github.io/autoformations-structurer/tutos/construire-algorithme/',NULL,1,5,1,11,NULL,'2026-09-09 06:58:52','2026-09-10 12:50:16',0),(21,'T.201.121','DMB-T.201.121','Comprendre les dépendances fonctionnelles','https://solicode-web-mobile.github.io/autoformations-structurer/tutos/comprendre-d%C3%A9pendances-fonctionnelles/',NULL,1,2,1,12,NULL,'2026-09-09 10:59:38','2026-09-09 11:04:53',0),(22,'T.201.122','DMB-T.201.122','Décomposer les données','https://solicode-web-mobile.github.io/autoformations-structurer/tutos/decomposer-les-donnees/',NULL,1,3,1,12,NULL,'2026-09-09 11:00:13','2026-09-09 11:04:53',0),(24,'T.201.131','DMB-T.201.131','Identifier les associations et les cardinalités','https://solicode-web-mobile.github.io/autoformations-structurer/tutos/associations-cardinalites/',NULL,1,1,1,13,NULL,'2026-09-09 11:04:53','2026-09-09 11:04:53',0);
