--
-- Table structure for table `taches`
--

DROP TABLE IF EXISTS `taches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `taches` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `titre` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `dateDebut` datetime DEFAULT NULL,
  `dateFin` datetime DEFAULT NULL,
  `reference` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ordre` int DEFAULT NULL,
  `priorite` int DEFAULT NULL COMMENT 'Niveau de priorité de la tâche, peut être NULL',
  `projet_id` bigint unsigned NOT NULL,
  `phase_projet_id` bigint unsigned DEFAULT NULL,
  `note` double DEFAULT NULL,
  `is_live_coding_task` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Indique si la tâche fait partie du live coding des apprenants',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `phase_evaluation_id` bigint unsigned DEFAULT NULL,
  `chapitre_id` bigint unsigned DEFAULT NULL,
  `mobilisation_ua_id` bigint unsigned DEFAULT NULL,
