INSERT INTO `unite_apprentissages` VALUES (1,'UA.111.11','DWB-UA.111.11','Identifier le contexte et les acteurs',NULL,'Analyser un support fonctionnel fourni afin d’identifier la finalité générale de l’application son domaine fonctionnel son périmètre et les différents acteurs concernés.',24,3,'2026-09-07 06:32:42','2026-09-09 10:58:19'),(2,'UA.112.11','DWB-UA.112.11','Comprendre le rôle des données dans une application',NULL,'Comprendre pourquoi une application informatique a besoin de données structurées et identifier les principales données nécessaires à son fonctionnement.',25,4,'2026-09-07 06:32:42','2026-09-09 10:58:19'),(3,'UA.121.11','DWB-UA.121.11','Manipuler les variables et les entrées-sorties',NULL,'Construire un traitement JavaScript simple permettant de stocker des valeurs recevoir des données et produire un résultat observable.',21,5,'2026-09-07 06:32:42','2026-09-09 10:58:19'),(4,'UA.125.21','DWB-UA.125.21','Déboguer un programme JavaScript',NULL,'Apprendre à trouver une erreur dans un programme JavaScript en l’exécutant ligne par ligne avec VS Code.',19,13,'2026-09-07 06:32:42','2026-09-09 10:58:19'),(5,'UA.161.11','DWB-UA.161.11','Partager un document Google Docs','https://solicode-web-mobile.github.io/autoformations-web/premiers-pas-web/google-slides-partage/',NULL,7,2,'2026-09-07 06:32:42','2026-09-09 10:58:19'),(6,'UA.161.12','DWB-UA.161.12','Découvrir le Web et Internet','https://solicode-web-mobile.github.io/autoformations-web/premiers-pas-web/web-internet/',NULL,8,2,'2026-09-07 06:32:42','2026-09-09 10:58:19'),(7,'UA.161.13','DWB-UA.161.13','Découvrir les langages du Web',NULL,NULL,9,2,'2026-09-07 06:32:42','2026-09-09 10:58:19'),(8,'UA.161.14','DWB-UA.161.14','Découvrir le métier de développeur',NULL,NULL,10,2,'2026-09-07 06:32:42','2026-09-09 10:58:19'),(9,'UA.162.11','DWB-UA.162.11','Apprendre à Solicode',NULL,'<div>&nbsp; Découvrir le parcours d\'apprentissage basé sur la pratique, l\'expérimentation&nbsp;</div><div>&nbsp; et la construction progressive (Tutoriels, Labs, Prototypes, Projet Fil Rouge&nbsp;</div><div>&nbsp; et Présentation) pour devenir un apprenant acteur de sa formation.</div>',5,1,'2026-09-07 06:32:42','2026-09-09 10:58:19'),(10,'UA.201.11','DMB-UA.021.11','De la maquette au dictionnaire de données',NULL,NULL,4,18,'2026-09-08 12:51:12','2026-09-09 10:58:19'),(11,'UA.201.21','DMB-UA.201.21','Apprendre les techniques algorithmiques',NULL,NULL,1,19,'2026-09-09 06:55:01','2026-09-09 06:55:01'),(12,'UA.201.12','DMB-UA.201.12','Analyser les données et identifier les entités',NULL,NULL,2,18,'2026-09-09 10:58:00','2026-09-09 10:58:00'),(13,'UA.201.13','DMB-UA.201.13','Construire le MCD',NULL,NULL,3,18,'2026-09-09 10:58:19','2026-09-09 10:58:19');
